import logging

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn
from flag_gems.utils import libentry

logger = logging.getLogger(__name__)

# A wide tile keeps the per-iteration histogram setup (shared-memory counter
# clear) amortised over many samples; 8192 float32 is 32 KB, well inside UB.
_BLOCK_SIZE = 8192
# Cap on the number of programs.  Beyond this the per-program register
# accumulator and the closing vector atomic stop paying for themselves.
_MAX_GRID_X = 1024


@libentry()
@triton.jit
def histc_kernel(
    inp_ptr,
    out_ptr,
    n_elements,
    bins: tl.constexpr,
    BINS_PAD: tl.constexpr,
    min_val,
    max_val,
    bin_scale,
    BLOCK_SIZE: tl.constexpr,
    TAIL: tl.constexpr,
):
    """Compute a histogram of ``inp_ptr`` into the ``bins`` counters at ``out_ptr``.

    Each program builds a per-block histogram in shared memory with
    ``tl.histogram`` and accumulates it in registers, so the global atomic
    traffic is one vector update per bin per program instead of one update per
    element.  The launch grid is capped (see ``_MAX_GRID_X``) and the loop walks
    the remaining blocks, which keeps huge inputs from overflowing the device's
    grid-dimension limit.

    ``bin_scale`` is precomputed on the host (one division per element is slow
    on accelerators without a hardware divide).  When the sample count is not a
    multiple of ``BLOCK_SIZE`` the tail block reads through an index clamped
    back into the tensor, because a masked load issues its whole vector and
    would read past the end of the allocation.
    """
    pid = tl.program_id(0)
    n_prog = tl.num_programs(0)
    bin_ids = tl.arange(0, BINS_PAD)
    valid_bins = bin_ids < bins
    lanes = tl.arange(0, BLOCK_SIZE)
    # Accumulate in int32: the counter vector is converted to the output dtype
    # once, instead of once per iteration.
    acc = tl.zeros([BINS_PAD], dtype=tl.int32)

    n_blocks = tl.cdiv(n_elements, BLOCK_SIZE)
    block = pid
    while block < n_blocks:
        if TAIL:
            offs = block * BLOCK_SIZE + lanes
            valid = offs < n_elements
            inp_val = tl.load(inp_ptr + tl.where(valid, offs, 0)).to(tl.float32)
            in_range = (inp_val >= min_val) & (inp_val <= max_val) & valid
        else:
            inp_val = tl.load(inp_ptr + block * BLOCK_SIZE + lanes).to(tl.float32)
            in_range = (inp_val >= min_val) & (inp_val <= max_val)
        # PyTorch's bin formula; values equal to ``max`` land in the last bin,
        # which ``minimum`` folds in without a second comparison.
        bin_idx = tl.floor((inp_val - min_val) * bin_scale).to(tl.int32)
        bin_idx = tl.minimum(bin_idx, bins - 1)
        # ``tl.histogram`` counts out-of-range values in bin 0 instead of
        # dropping them, so park discarded samples in the padding slot
        # (``bins <= BINS_PAD - 1``) and drop that slot below.
        bin_idx = tl.where(in_range, bin_idx, bins)
        acc += tl.histogram(bin_idx, BINS_PAD)
        block += n_prog

    tl.atomic_add(
        out_ptr + bin_ids,
        acc.to(out_ptr.dtype.element_ty),
        mask=valid_bins,
        sem="relaxed",
    )


def histc(inp, bins=100, min=0, max=0):
    """
    Compute the histogram of a tensor.

    Args:
        inp: Input tensor
        bins: Number of histogram bins (default: 100)
        min: Lower end of the range (inclusive). If min == max == 0, uses data min.
        max: Upper end of the range (inclusive). If min == max == 0, uses data max.

    Returns:
        Tensor: Histogram represented as a tensor of shape (bins,)
    """
    logger.debug("GEMS HISTC")

    # Ensure input is contiguous
    inp = inp.contiguous()

    # Get min and max values
    min_val = float(min)
    max_val = float(max)

    if min_val == 0 and max_val == 0:
        # Use actual min/max of the data
        min_val = float(inp.min().item())
        max_val = float(inp.max().item())

    # Handle edge case where min == max
    if min_val == max_val:
        # All elements go to the first bin if they equal min_val
        out = torch.zeros(bins, dtype=inp.dtype, device=inp.device)
        # Count how many elements equal min_val (excluding NaN)
        count = ((inp == min_val) & ~inp.isnan()).sum().item()
        out[0] = count
        return out

    # Create output histogram tensor
    out = torch.zeros(bins, dtype=inp.dtype, device=inp.device)

    n_elements = inp.numel()

    if n_elements == 0:
        return out

    # Pick the block so that the launch still fills the vector cores: a block of
    # 8192 would compute a 4K-sample histogram on a single core, which is far
    # slower than spreading a few hundred samples over every core.  The floor
    # keeps the per-block histogram setup (one counter per bin) amortised.
    block_size = triton.next_power_of_2(triton.cdiv(n_elements, 256))
    if block_size < 256:
        block_size = 256
    elif block_size > _BLOCK_SIZE:
        block_size = _BLOCK_SIZE

    # The grid is capped and each program walks the rest of the blocks.  A
    # modest persistent grid keeps the per-program accumulator (and hence the
    # closing atomic) count low.
    grid_x = triton.cdiv(n_elements, block_size)
    if grid_x > _MAX_GRID_X:
        grid_x = _MAX_GRID_X
    grid = (grid_x,)
    # One extra (padding) bin keeps discarded samples out of the real bins;
    # the power-of-two size also keeps `tl.arange`/`tl.histogram` in range.
    bins_pad = triton.next_power_of_2(bins + 1)
    bin_scale = bins / (max_val - min_val)

    with torch_device_fn.device(inp.device):
        histc_kernel.run(
            inp,
            out,
            n_elements,
            bins,
            bins_pad,
            min_val,
            max_val,
            bin_scale,
            BLOCK_SIZE=block_size,
            TAIL=n_elements % block_size != 0,
            grid=grid,
            warmup=False,
        )

    return out
